+      </div>
+
+      <div class="example">
+        <h2>
+          <button class="faq-trigger" type="button" aria-expanded="false" aria-controls="faq-4">
+            <span class="question-text">Why do cats stare at you?</span>
+            <span class="chevron" aria-hidden="true"></span>
+          </button>
+        </h2>
+        <div class="details" id="faq-4">
+          <p>Cats stare to read your body language, check whether you are moving, and sometimes to ask for attention or food.</p>
+        </div>
+      </div>
+
+      <div class="example">
+        <h2>
+          <button class="faq-trigger" type="button" aria-expanded="false" aria-controls="faq-5">
+            <span class="question-text">Do indoor cats need enrichment?</span>
+            <span class="chevron" aria-hidden="true"></span>
+          </button>
+        </h2>
+        <div class="details" id="faq-5">
+          <p>Yes. Toys, climbing spots, scratching posts, and short play sessions help indoor cats stay healthy and mentally engaged.</p>
+        </div>
+      </div>
+    </div>
+  </main>
+
+  <script>
+    const disclosures = document.querySelectorAll('.example');
+
+    disclosures.forEach((example) => {
+      const trigger = example.querySelector('.faq-trigger');
+      const panel = example.querySelector('.details');
+
+      panel.hidden = true;
+      trigger.setAttribute('aria-expanded', 'false');
+
+      const setOpen = (open) => {
+        trigger.setAttribute('aria-expanded', String(open));
+        panel.hidden = !open;
+      };
+
+      trigger.addEventListener('click', () => {
+        const open = trigger.getAttribute('aria-expanded') === 'true';
+        setOpen(!open);
+      });
+
+      trigger.addEventListener('keydown', (event) => {
+        if (event.key === 'Escape' && trigger.getAttribute('aria-expanded') === 'true') {
+          event.preventDefault();
+          setOpen(false);
+          trigger.focus();
+        }
+      });
+    });
+  </script>
+</body>
